css:
:scope { width: min(100%, 1338px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 24; grid-row: 1 / span 3; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.22em; text-transform: uppercase; text-align: center; color: var(--os-color-link); }
.gx__i2 { grid-column: 5 / span 15; grid-row: 5 / span 48; font-family: var(--os-font-heading); font-size: 93.7px; font-weight: 700; line-height: 1; letter-spacing: -0.025em; text-align: center; color: var(--os-color-text); }
.gx__i3 { grid-column: 6 / span 13; grid-row: 56 / span 13; font-family: var(--os-font-body); font-size: 24.9px; font-weight: 400; line-height: 1.38; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
.gx__i4 { grid-column: 5 / span 10; grid-row: 73 / span 7; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.2em; text-transform: uppercase; text-align: center; color: var(--os-color-surface); }
.gx__i4 { justify-self: center; }
.gx__i5 { grid-column: 15 / span 5; grid-row: 73 / span 7; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.2em; text-transform: uppercase; text-align: center; color: var(--os-color-text); }
.gx__i5 { justify-self: center; }
.gx__i6 { grid-column: 6 / span 13; grid-row: 92 / span 5; font-family: var(--os-font-body); font-size: 24.9px; font-weight: 300; line-height: 1.55; letter-spacing: 0em; font-style: italic; text-align: center; color: var(--os-color-text); }
.gx__i7 { grid-column: 6 / span 13; grid-row: 98 / span 4; font-family: var(--os-font-body); font-size: 19.7px; font-weight: 400; line-height: 1.55; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
.gx__i8 { grid-column: 6 / span 13; grid-row: 103 / span 4; font-family: var(--os-font-body); font-size: 19.7px; font-weight: 400; line-height: 1.55; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i2 { font-family: var(--os-font-heading); font-size: 75px; }
  .gx__i3 { font-family: var(--os-font-body); font-size: 20px; }
  .gx__i4 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i5 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i6 { font-family: var(--os-font-body); font-size: 20px; }
  .gx__i7 { font-family: var(--os-font-body); font-size: 16px; }
  .gx__i8 { font-family: var(--os-font-body); font-size: 16px; }
}
